from pathlib import Path
import sys, html
sys.path.insert(0, str(Path('backend').resolve()))
from app.core.permissions import ROLE_PERMISSIONS
out=Path('docs/diagrams')
css='''*{box-sizing:border-box}body{margin:0;background:#f4f1f8;color:#272036;font-family:Arial,sans-serif}main{width:1440px;margin:auto;padding:44px}header{background:linear-gradient(120deg,#251932,#654474);color:white;padding:44px 48px;border-radius:28px;position:relative;overflow:hidden}header:after{content:"";position:absolute;width:360px;height:360px;border:1px solid #ffffff22;border-radius:50%;right:-80px;top:-120px;box-shadow:0 0 0 55px #ffffff06,0 0 0 110px #ffffff04}header small{color:#d2bde4;letter-spacing:3px;font-weight:bold;font-size:15px}h1{font-size:56px;letter-spacing:-2px;margin:18px 0 8px}header p{font-size:23px;color:#e1d6ea;margin:0;line-height:1.5}.meta{display:flex;justify-content:space-between;align-items:center;margin:26px 4px;font-size:16px;color:#6c607b}.legend{display:flex;gap:24px}.dot{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:9px}.purple{background:#856099}.teal{background:#238c83}.block{background:white;border:1px solid #ddd2e6;border-radius:22px;padding:25px 30px;box-shadow:0 7px 0 #e8e0ef;position:relative}.title{display:flex;align-items:center;gap:18px;margin-bottom:20px}.num{width:52px;height:52px;display:grid;place-items:center;background:#eee5f5;color:#704783;border-radius:15px;font-size:21px;font-weight:bold}.title h2{font-size:25px;margin:0;letter-spacing:-.4px}.tag{margin-left:auto;font-size:12px;letter-spacing:2px;color:#8c7d99}.cols{display:grid;grid-template-columns:1fr 1fr;gap:24px}.panel{border-radius:14px;padding:17px 22px;background:#f8f4fb}.panel.extra{background:#edf7f4}.panel h3{font-size:13px;text-transform:uppercase;letter-spacing:2px;color:#80528e;margin:0 0 12px}.extra h3{color:#257f77}ul{margin:0;padding-left:19px}li{font-size:18px;line-height:1.55;margin:3px 0;color:#4e455a}li::marker{color:#9e7ab0}.extra li::marker{color:#42958c}.connector{height:35px;text-align:center;color:#9477a5;font-size:27px;line-height:35px}.band{margin-top:30px;padding:25px 30px;border-radius:20px;background:#2f223d;color:white}.band h3{margin:0 0 16px;font-size:15px;letter-spacing:2px;color:#d3bedf}.chips{display:flex;gap:12px;flex-wrap:wrap}.chip{padding:12px 20px;border-radius:10px;background:#ffffff10;border:1px solid #ffffff20;font-size:17px}.foot{font-size:15px;line-height:1.6;color:#796c85;margin:22px 5px 0}.roles{display:grid;grid-template-columns:repeat(5,1fr);gap:12px;margin:26px 0}.role{background:white;border:1px solid #dfd5e7;border-radius:14px;padding:20px}.role h3{font-size:18px;margin:0 0 10px;color:#624577}.role p{font-size:16px;line-height:1.5;color:#786980;margin:0}.tablewrap{border-radius:20px;overflow:hidden;border:1px solid #ded4e6;background:white}table{border-collapse:collapse;width:100%;font-size:17px}th{background:#372644;color:#fff;text-align:center;padding:22px 12px;font-size:15px;line-height:1.5}th:first-child{text-align:left;width:36%;padding-left:25px}td{padding:15px 12px;text-align:center;border-bottom:1px solid #eee8f2}td:first-child{text-align:left;padding-left:25px;font-size:17px}tr:nth-child(even){background:#faf8fc}.yes{color:#16796d;font-weight:bold}.no{color:#aaa0b2}.self{display:inline-block;background:#eee5f5;color:#76508a;border-radius:6px;padding:4px 12px;font-size:14px}.all{color:#16796d;font-size:15px;font-weight:bold}'''
def page(title,sub,body):
 return '<!doctype html><html lang="en"><head><meta charset="utf-8"><title>'+title+'</title><style>'+css+'</style></head><body><main><header><small>TEAM 726 / FINAL SUBMISSION</small><h1>'+title+'</h1><p>'+sub+'</p></header>'+body+'</main></body></html>'
blocks=[
('Employee & access','PEOPLE + PERMISSIONS', ['Employee records, list and card views','Admin-created accounts linked to employees','Contracts, attendance and leave history'],['Automatic employee references','Role-aware views and record ownership','Field audit history; current permission checks']),
('Contracts & working schedules','TERMS + TIME', ['Dated contracts and monthly wage','Weekly schedule intervals and break allowances','Applicable contract selected for payroll period'],['Automatic contract references and overlap checks','Historical contract resolution for past payroll','Derived schedule hours and live salary burn']),
('Attendance','DAILY OPERATIONS', ['Personal check-in / checkout and elapsed timer','Worked hours, status and employee history','Manual attendance corrections with a reason'],['Location checks and outside-office flags','One daily session with scheduled break deduction','Status rules, audit trail and paginated history']),
('Time off & allocations','REQUEST + DECISION', ['Leave types, allocations and date-based requests','Approve / refuse and track available balance','Type settings control allocation and approval'],['Allocation days and dates calculate each other','Locked approvals prevent double consumption','Paid-leave balance blocker; auto-approval by type']),
('Salary structures & rules','CONFIGURE + CALCULATE', ['Salary structures with sequenced salary rules','Fixed, Percentage and Formula computation','Basic, allowances, deductions, Gross and Net'],['Safe arithmetic formula validation','Schedule, worked-hours and unpaid-days inputs','Explicit WAGE formulas; Decimal calculations']),
('Payruns, payslips & insights','REVIEW + FINALIZE', ['Scope first, then select employees and create','Draft → Computed → Validated → Paid','Payslip salary breakdown and paid-only PDF'],['Missing-data and duplicate-payslip diagnostics','QR verification and persistent read-all notifications','Filtered live dashboard and retained paid history'])]
body='<div class="meta"><span>PEOPLEPAY360 / END-TO-END MASTER FLOW</span><div class="legend"><span><i class="dot purple"></i>Core workflow</span><span><i class="dot teal"></i>Added capabilities</span></div></div>'
for i,(title,tag,core,extra) in enumerate(blocks):
 if i: body+='<div class="connector">↓</div>'
 body+=f'<section class="block"><div class="title"><div class="num">0{i+1}</div><h2>{html.escape(title)}</h2><span class="tag">{tag}</span></div><div class="cols">'
 for label,items,cl in [('Core workflow',core,''),('Added capabilities',extra,' extra')]:
  body+=f'<div class="panel{cl}"><h3>{label}</h3><ul>'+''.join('<li>'+html.escape(t)+'</li>' for t in items)+'</ul></div>'
 body+='</div></section>'
body+='<div class="band"><h3>ONE SHARED PLATFORM</h3><div class="chips">'+''.join('<span class="chip">'+s+'</span>' for s in ['React + Vite','Tailwind CSS','FastAPI','SQLAlchemy','MySQL','JWT + RBAC','ReportLab + QR'])+'</div></div>'
body+='<p class="foot">Workflow arrows show the employee lifecycle, not a requirement to complete every module before the next.<br>Day-based leave • Configured formulas determine salary impact • Single-company deployment • Optional SMTP; no WhatsApp integration<br>Source: final implementation and Excalidraw audit · 6 September 2026 · Sanket Prajapati & Manav Joshi</p>'
(out/'peoplepay360-master-flow.html').write_text(page('PeoplePay360','From joining day to payday.<br>Six connected modules. Core workflows and added capabilities.',body),encoding='utf8')
roles=list(ROLE_PERMISSIONS)
purpose=['Personal records, attendance, leave and payslips.','Employees and everyday HR operations.','HR operations and payroll preparation.','HR, salary configuration and payroll finalization.','All permissions, accounts and role assignments.']
body='<div class="roles">'+''.join(f'<div class="role"><h3>{r}</h3><p>{p}</p></div>' for r,p in zip(roles,purpose))+'</div>'
rows=[('View employee records','employee.read_all','employee.read_self'),('Create, edit and archive employees','employee.create',None),('View contracts','contract.read','contract'),('Create and edit contracts','contract.create',None),('View working schedules','schedule.read',None),('Manage working schedules','schedule.manage',None),('Personal check-in / checkout','attendance.create_self',None),('View attendance','attendance.read_all','attendance.read_self'),('Correct attendance','attendance.correct',None),('Request personal time off','timeoff.request',None),('View time-off requests','timeoff.read_all','timeoff.read_self'),('Approve / refuse requests','timeoff.approve',None),('Manage allocations and leave types','timeoff.allocate',None),('Manage departments and positions','master_data.manage',None),('View payroll dashboard','dashboard.read',None),('View, create and compute payruns','payrun.compute',None),('Validate and mark payruns paid','payrun.mark_paid',None),('View salary structures and rules','salary_rule.read',None),('Manage salary structures and rules','salary_rule.manage',None),('View payslips','payslip.read_all','payslip.read_self'),('Download paid payslip PDFs','payslip.print','pdf'),('Send payslips through configured SMTP','payrun.send',None),('Read own notifications / mark read','notification.read_self',None),('Manage accounts and role assignments','user.manage',None)]
body+='<div class="tablewrap"><table><thead><tr><th>MODULE / OPERATION</th>'+''.join('<th>'+r.replace('HR Payroll ','HR Payroll<br>')+'</th>' for r in roles)+'</tr></thead><tbody>'
for name,perm,scope in rows:
 body+='<tr><td>'+name+'</td>'
 for role in roles:
  perms=ROLE_PERMISSIONS[role]; value='<span class="no">—</span>'
  if (scope in ('contract','pdf') and role=='Employee') or (scope not in (None,'contract','pdf') and scope in perms and perm not in perms): value='<span class="self">Own only</span>'
  elif perm in perms: value='<span class="all">All</span>' if scope and scope!='pdf' else '<span class="yes">✓</span>'
  body+='<td>'+value+'</td>'
 body+='</tr>'
body+='</tbody></table></div><p class="foot"><strong>✓ Allowed &nbsp; — Not granted &nbsp; Own only: linked personal records &nbsp; All: permitted organization records</strong><br>Default single-role permissions from backend/app/core/permissions.py. Multiple roles combine their permissions.<br>Personal actions require a linked employee. Status, ownership and business validations still apply; PDF downloads require Paid status.<br>Users cannot change their own roles. SMTP delivery requires configuration. Schedule viewing is available to authenticated users.<br>6 September 2026 · PeoplePay360 / Team 726</p>'
(out/'peoplepay360-role-permissions.html').write_text(page('The right access.','Five roles, one workspace.<br>Default permissions and record scope for PeoplePay360.',body),encoding='utf8')
print('Created two editable HTML diagrams')
